const out = [];
for (const u of ['https://cha0smagicklabs.com/tools/tarot-journal.html', 'https://cha0smagicklabs.com/blog/abraxas-annunaki.html']) {
  const p = await browser.open(u);
  await sleep(6000);
  const raw = await p.evaluate(() => { try {
    const res = performance.getEntriesByType('resource').map(r => r.name);
    const ga = res.filter(n => /google-analytics|g\/collect|googletagmanager/.test(n));
    const evs = [];
    for (const x of ga) { try { const q = new URL(x).searchParams; for (const k of ['en','ep','ev','tid']) { const v = q.get(k); if (v) evs.push(k + '=' + v) } } catch {} }
    const inline = Array.from(document.querySelectorAll('script')).map(s => s.textContent || '').join('\n');
    return { url: location.href.slice(0,70), title: document.title.slice(0,46), hasConfig: /gtag\(\s*['"]config['"]/.test(inline), gaCalls: ga.length, events: evs.slice(0,12), gaSample: ga.slice(0,2).map(x => x.slice(0,140)) };
  } catch (e) { return { err: String(e.message).slice(0,80) } } });
  const v = (raw && 'value' in raw) ? raw.value : raw;
  out.push(v);
  console.log('LIVE ' + JSON.stringify(v));
  await p.close();
}
return out;
